import { createChart, removeChart } from '../test/ut/core/utHelper';

function getVisualMapItems(chart: ReturnType<typeof createChart>) {
    chart.getZr().refreshImmediately();
    // Piece symbols are paths and labels are tspans inside the visualMap component.
    const items: { type: string; silent: boolean; cursor: string }[] = [];
    chart.getZr().storage.getDisplayList().forEach(function (el: any) {
        if (el.type === 'tspan' || el.type === 'path' || el.type === 'polygon' || el.type === 'circle') {
            items.push({ type: el.type, silent: !!el.silent, cursor: el.cursor });
        }
    });
    return items;
}

function makeOption(selectedMode: boolean | 'single' | 'multiple') {
    return {
        xAxis: {},
        yAxis: {},
        series: [{ type: 'scatter', data: [[12, 223], [50, 60], [200, 300]] }],
        visualMap: {
            type: 'piecewise',
            selectedMode: selectedMode,
            pieces: [
                { min: 200 },
                { min: 50, max: 200 },
                { max: 50 }
            ]
        }
    };
}

describe('visualmap-selectedmode-false-silent', function () {
    it('sets pieces and labels silent when selectedMode is false', function () {
        const chart = createChart();
        chart.setOption(makeOption(false) as any);
        const items = getVisualMapItems(chart);
        expect(items.length).toBeGreaterThan(0);
        items.forEach(function (el) {
            expect(el.silent).toBe(true);
        });
        removeChart(chart);
    });

    it('keeps pieces and labels interactive when selectedMode is enabled', function () {
        const chart = createChart();
        chart.setOption(makeOption('multiple') as any);
        const items = getVisualMapItems(chart);
        expect(items.length).toBeGreaterThan(0);
        items.forEach(function (el) {
            expect(el.silent).toBe(false);
        });
        removeChart(chart);
    });
});

import { createChart, removeChart } from '../test/ut/core/utHelper';

function getVisualMapPieceEls(chart: ReturnType<typeof createChart>) {
    chart.getZr().refreshImmediately();
    // Piecewise visualMap renders each piece as a Group with an `onclick`
    // handler containing the symbol (path) and the label (tspan).
    const els: { type: string; silent: boolean }[] = [];
    chart.getZr().storage.getDisplayList().forEach(function (el: any) {
        const parent = el.parent;
        if (parent && typeof parent.onclick === 'function'
            && (el.type === 'tspan' || el.isGroup === false)
        ) {
            els.push({ type: el.type, silent: !!el.silent });
        }
    });
    return els;
}

function makeOption(selectedMode: boolean | 'single' | 'multiple') {
    return {
        visualMap: {
            type: 'piecewise',
            selectedMode: selectedMode,
            dimension: 0,
            pieces: [
                { min: 200 },
                { min: 50, max: 200 },
                { max: 50 }
            ]
        },
        series: [{ type: 'scatter', data: [[12, 223], [50, 60], [200, 300]] }]
    };
}

describe('visualmap-selectedmode-false-silent', function () {
    it('sets pieces and labels silent when selectedMode is false', function () {
        const chart = createChart();
        chart.setOption(makeOption(false) as any);
        const els = getVisualMapPieceEls(chart);
        expect(els.length).toBeGreaterThan(0);
        els.forEach(function (el) {
            expect(el.silent).toBe(true);
        });
        removeChart(chart);
    });

    it('keeps pieces and labels interactive when selectedMode is enabled', function () {
        const chart = createChart();
        chart.setOption(makeOption('multiple') as any);
        const els = getVisualMapPieceEls(chart);
        expect(els.length).toBeGreaterThan(0);
        els.forEach(function (el) {
            expect(el.silent).toBe(false);
        });
        removeChart(chart);
    });
});
